public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    char[] S = sc.next().toCharArray();
    int[] C = new int[N];
    for (int i = 0; i < N; i++) {
        C[i] = sc.nextInt();
    }
    int[][][] dp = new int[N][2][2];
    dp[0][0][0] = 0;
    dp[0][1][0] = C[0];
    dp[0][0][1] = Integer.MAX_VALUE;
    dp[0][1][1] = Integer.MAX_VALUE;

    for (int i = 1; i < N; i++) {
        dp[i][0][0] = Math.min(dp[i - 1][0][0], dp[i - 1][1][0]);
        dp[i][1][0] = Math.min(dp[i - 1][0][0], dp[i - 1][1][0]) + C[i];
        dp[i][0][1] = Math.min(dp[i - 1][0][1], dp[i - 1][1][1]);
        if (S[i] == S[i - 1]) {
            dp[i][0][1] = Math.min(dp[i][0][1], dp[i - 1][0][0]);
        }
        dp[i][1][1] = Math.min(dp[i - 1][0][1], dp[i - 1][1][1]) + C[i];
        if (S[i] == S[i - 1]) {
            dp[i][1][1] = Math.min(dp[i][1][1], dp[i - 1][0][0] + C[i]);
        }
    }

    System.out.println(Math.min(dp[N - 1][0][1], dp[N - 1][1][1]));
}
